//  AgentAvatarView.swift
//  bighelp agent avatars for SwiftUI. Generated by tools/build.py; regenerate rather than edit presets by hand.
//
//  Setup: add every file in /svg to your app target (Copy Bundle Resources).
//
//  AgentAvatarView(.lobster, colors: .neon, state: agent.isStreaming ? .talking : .idle)
//      .frame(width: 96, height: 96)
//
//  Bits (geometric bots) also take a face:
//  AgentAvatarView(.orb, face: .init(eyes: .visor, mouth: .fang, accessory: .headset), state: .waiting)
//
//  Tapping squishes the avatar and calls onPoke. The eyes follow touches over the avatar.

import SwiftUI
import WebKit

