/*__STATECASES__*/
}

public enum AgentAvatarCharacter: String, CaseIterable, Sendable {
/*__CASES__*/

    public var displayName: String {
        switch self {
/*__NAMES__*/
        }
    }

    /// Bits are the geometric bots that accept an `AgentAvatarFace`.
    public var isBit: Bool {
        switch self {
/*__ISBIT__*/
        }
    }
}

public enum AgentAvatarEyes: String, CaseIterable, Codable, Sendable {
/*__EYES__*/
}

public enum AgentAvatarMouth: String, CaseIterable, Codable, Sendable {
/*__MOUTHS__*/
}

public enum AgentAvatarAccessory: String, CaseIterable, Codable, Sendable {
/*__ACCS__*/
}

/// Face options for Bits. Nil values use that Bit's own defaults; classic characters ignore this.
public struct AgentAvatarFace: Equatable, Codable, Sendable {
    public var eyes: AgentAvatarEyes?
    public var mouth: AgentAvatarMouth?
    public var accessory: AgentAvatarAccessory?
    public var cheeks: Bool

    public init(eyes: AgentAvatarEyes? = nil, mouth: AgentAvatarMouth? = nil,
                accessory: AgentAvatarAccessory? = nil, cheeks: Bool = true) {
        self.eyes = eyes; self.mouth = mouth; self.accessory = accessory; self.cheeks = cheeks
    }

    public static let `default` = AgentAvatarFace()

    var json: String {
        guard let data = try? JSONEncoder().encode(self), let s = String(data: data, encoding: .utf8) else { return "{}" }
        return s
    }
}

/// A colorway. Any nil value falls back to the character's own palette.
public struct AgentAvatarColors: Equatable, Sendable, Codable {
    public var primary: String?
    public var secondary: String?
    public var accent: String?
    public var background: String?
    public var ink: String?
    public var skin: String?

    public init(primary: String? = nil, secondary: String? = nil, accent: String? = nil,
                background: String? = nil, ink: String? = nil, skin: String? = nil) {
        self.primary = primary; self.secondary = secondary; self.accent = accent
        self.background = background; self.ink = ink; self.skin = skin
    }

    /// Overlay per-agent overrides on top of a preset.
    public func merged(with other: AgentAvatarColors) -> AgentAvatarColors {
        AgentAvatarColors(primary: other.primary ?? primary, secondary: other.secondary ?? secondary,
                          accent: other.accent ?? accent, background: other.background ?? background,
                          ink: other.ink ?? ink, skin: other.skin ?? skin)
    }

/*__PRESETS__*/

    var json: String {
        guard let data = try? JSONEncoder().encode(self), let s = String(data: data, encoding: .utf8) else { return "{}" }
        return s
    }
}

public struct AgentAvatarView: UIViewRepresentable {
    public var character: AgentAvatarCharacter
    public var colors: AgentAvatarColors
    public var face: AgentAvatarFace
    public var state: AgentAvatarState
    public var showsBackground: Bool
    public var tracksTouch: Bool
    public var onPoke: (() -> Void)?

    public init(_ character: AgentAvatarCharacter,
                colors: AgentAvatarColors = .original,
                face: AgentAvatarFace = .default,
                state: AgentAvatarState = .idle,
                showsBackground: Bool = true,
                tracksTouch: Bool = true,
                onPoke: (() -> Void)? = nil) {
        self.character = character
        self.colors = colors
        self.face = face
        self.state = state
        self.showsBackground = showsBackground
        self.tracksTouch = tracksTouch
        self.onPoke = onPoke
    }

    public func makeCoordinator() -> Coordinator { Coordinator() }

    public func makeUIView(context: Context) -> WKWebView {
        let controller = WKUserContentController()
        controller.add(WeakMessageHandler(context.coordinator), name: "bhPoke")
        let config = WKWebViewConfiguration()
        config.userContentController = controller
        config.suppressesIncrementalRendering = true

        let web = WKWebView(frame: .zero, configuration: config)
        web.isOpaque = false
        web.backgroundColor = .clear
        web.scrollView.backgroundColor = .clear
        web.scrollView.isScrollEnabled = false
        web.scrollView.bounces = false
        web.scrollView.contentInsetAdjustmentBehavior = .never
        web.navigationDelegate = context.coordinator
        web.isAccessibilityElement = true
        web.accessibilityLabel = character.displayName

        context.coordinator.parent = self
        context.coordinator.load(into: web)
        return web
    }

    public func updateUIView(_ web: WKWebView, context: Context) {
        context.coordinator.parent = self
        web.accessibilityLabel = character.displayName
        if context.coordinator.loaded != character {
            context.coordinator.load(into: web)
        } else {
            context.coordinator.sync(web)
        }
    }

    public static func dismantleUIView(_ web: WKWebView, coordinator: Coordinator) {
        web.configuration.userContentController.removeScriptMessageHandler(forName: "bhPoke")
    }

    @MainActor
    public final class Coordinator: NSObject, WKNavigationDelegate, WKScriptMessageHandler {
        var parent: AgentAvatarView?
        var loaded: AgentAvatarCharacter?
        private var ready = false

        func load(into web: WKWebView) {
            guard let p = parent else { return }
            loaded = p.character
            ready = false
            guard let url = Bundle.main.url(forResource: p.character.rawValue, withExtension: "svg"),
                  let svg = try? String(contentsOf: url, encoding: .utf8) else {
                assertionFailure("\(p.character.rawValue).svg is missing from the app bundle")
                return
            }
            web.loadHTMLString(Self.page(svg: svg, initialCall: call(for: p)), baseURL: nil)
        }

        func sync(_ web: WKWebView) {
            guard ready, let p = parent else { return }
            web.evaluateJavaScript(call(for: p), completionHandler: nil)
        }

        private func call(for p: AgentAvatarView) -> String {
            "window.bh&&bh.set('\(p.state.rawValue)',\(p.colors.json),\(p.showsBackground),\(p.tracksTouch),\(p.face.json));"
        }

        public func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
            ready = true
            sync(webView)
        }

        public func userContentController(_ userContentController: WKUserContentController,
                                          didReceive message: WKScriptMessage) {
            parent?.onPoke?()
        }

        static func page(svg: String, initialCall: String) -> String {
            """
            <!doctype html><html><head>
            <meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
            <style>html,body{margin:0;width:100%;height:100%;background:transparent;overflow:hidden;\
            -webkit-user-select:none;-webkit-touch-callout:none}svg{width:100%;height:100%;display:block}</style>
            </head><body>\(svg)<script>
            (function(){
              var svg=document.querySelector('svg'),track=true,
                  F={eyes:'data-eyes',mouth:'data-mouth',accessory:'data-acc'},D={},
                  V={primary:'--av-primary',secondary:'--av-secondary',accent:'--av-accent',background:'--av-bg',ink:'--av-ink',skin:'--av-skin'};
              for(var f in F)D[f]=svg.getAttribute(F[f]);
              function clamp(v){return Math.max(-1,Math.min(1,v)).toFixed(3)}
              function look(x,y){svg.style.setProperty('--lx',clamp(x));svg.style.setProperty('--ly',clamp(y))}
              function lookAt(e){var r=svg.getBoundingClientRect();look((e.clientX-r.left-r.width/2)/(r.width/2),(e.clientY-r.top-r.height*.45)/(r.height/2))}
              window.bh={set:function(state,colors,bg,t,face){
                svg.setAttribute('data-state',state);svg.setAttribute('data-bg',bg?'on':'off');
                if(D.eyes){face=face||{};for(var f in F)svg.setAttribute(F[f],face[f]||D[f]);
                  svg.setAttribute('data-cheeks',face.cheeks===false?'off':'on');}
                for(var k in V){colors[k]?svg.style.setProperty(V[k],colors[k]):svg.style.removeProperty(V[k])}
                track=t;if(!t)look(0,0);
              }};
              addEventListener('pointerdown',function(e){
                svg.classList.remove('bh-poke');void svg.getBoundingClientRect();svg.classList.add('bh-poke');
                if(track)lookAt(e);
                window.webkit&&webkit.messageHandlers.bhPoke&&webkit.messageHandlers.bhPoke.postMessage(1);
              });
              addEventListener('pointermove',function(e){if(track)lookAt(e)});
              addEventListener('pointerup',function(){setTimeout(function(){look(0,0)},700)});
              svg.addEventListener('animationend',function(e){if(e.animationName==='bh-squish')svg.classList.remove('bh-poke')});
              \(initialCall)
            })();
            </script></body></html>
            """
        }
    }
}

/// Avoids the retain cycle WKUserContentController creates with its handlers.
@MainActor
private final class WeakMessageHandler: NSObject, WKScriptMessageHandler {
    weak var target: WKScriptMessageHandler?
    init(_ target: WKScriptMessageHandler) { self.target = target }
    func userContentController(_ controller: WKUserContentController, didReceive message: WKScriptMessage) {
        target?.userContentController(controller, didReceive: message)
    }
}

